// Exact exhaustive q25 three-block affine Singer spectrum redundancy.
// Input generated by generate.py. 780 choose 3 = 78,788,060 triples.
// C++17, no external dependencies. A result is a NECESSARY repair bound.
#include <cstdint>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <vector>
using namespace std;
struct Spectrum { int u,c; uint64_t bits[11]; };
struct Prefix { int r; uint64_t bits[11]; };
int choose2(int x) { return x*(x-1)/2; }
int deletion_floor(int R) {
  const int K=26, m=3, n=325;
  for(int D=0;D<=m*K;D++) {
    int S=m*K-D, a=S/m, t=S%m;
    int remaining=(m-t)*choose2(a)+t*choose2(a+1);
    if(m*n-remaining>=R) return D;
  }
  throw runtime_error("no deletion bound");
}
int main(int argc,char** argv) {
  if(argc!=3) {cerr<<"usage: enumerate states.tsv prefixes.tsv\n";return 2;}
  ifstream f(argv[1]),g(argv[2]);
  if(!f||!g)throw runtime_error("missing inputs");
  vector<Spectrum> states;Spectrum s;
  while(f>>s.u>>s.c) {for(auto &z:s.bits) {if(!(f>>z))throw runtime_error("bad state");}states.push_back(s);}
  if(states.size()!=780)throw runtime_error("wrong unique-state count");
  Prefix prefixes[4];
  for(auto &p:prefixes) {if(!(g>>p.r))throw runtime_error("bad prefix");for(auto &z:p.bits)if(!(g>>z))throw runtime_error("bad prefix bits");}
  const int expect_r[4]={0,5,13,26};for(int p=0;p<4;p++)if(prefixes[p].r!=expect_r[p])throw runtime_error("wrong prefix ordering");
  int best[4]={10000,10000,10000,10000};
  int wi[4]={},wj[4]={},wk[4]={};uint64_t checked=0;
  const int N=(int)states.size();
  for(int i=0;i<N;i++)for(int j=i+1;j<N;j++) {
    uint64_t pair[11];for(int t=0;t<11;t++)pair[t]=states[i].bits[t]|states[j].bits[t];
    for(int k=j+1;k<N;k++) {
      int covered[4]={0,0,0,0};
      for(int t=0;t<11;t++) {
        uint64_t all=pair[t]|states[k].bits[t];
        covered[0]+=__builtin_popcountll(all);
        for(int p=1;p<4;p++)covered[p]+=__builtin_popcountll(all|prefixes[p].bits[t]);
      }
      checked++;
      for(int p=0;p<4;p++) {
        int R=3*325+choose2(prefixes[p].r)-covered[p];
        if(R<best[p]) {best[p]=R;wi[p]=i;wj[p]=j;wk[p]=k;}
      }
    }
  }
  if(checked!=78788060ULL)throw runtime_error("incomplete triple search");
  const int expected_R[4]={415,425,492,715};
  const int expected_D[4]={19,20,23,37};
  cout<<"COUNT "<<states.size()<<" "<<checked<<"\n";
  for(int p=0;p<4;p++) {
    int D=deletion_floor(best[p]);
    if(best[p]!=expected_R[p]||D!=expected_D[p])throw runtime_error("regression in exact triple floor");
    auto a=states[wi[p]],b=states[wj[p]],c=states[wk[p]];
    cout<<"RESULT "<<prefixes[p].r<<" "<<best[p]<<" "<<D<<" "
        <<a.u<<" "<<a.c<<" "<<b.u<<" "<<b.c<<" "<<c.u<<" "<<c.c<<"\n";
  }
  cout<<"PASS complete exact q25 triple enumeration; no global Sidon/novelty claim\n";
}
